def extract_state_joints(traj: pd.DataFrame, columns: list[str]):
    np_dict = {}
    for column in columns:
        np_dict[column] = np.vstack([arr for arr in traj[column]])
    return np.concatenate([np_dict[column] for column in columns], axis=-1)

